import os
import sys
import sqlite3
import zipfile

if sys.platform == 'win32':
    sys.stdout.reconfigure(encoding='utf-8')

DATA_DIR = os.path.join(os.path.dirname(__file__), 'data')
DB_PATH = os.path.join(DATA_DIR, 'thai_law.db')
ZIP_PATH = os.path.join(DATA_DIR, 'thai_law.db.zip')

def init_db(conn):
    cursor = conn.cursor()
    
    # 1. legal_sections
    cursor.execute('''
    CREATE TABLE IF NOT EXISTS legal_sections (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        law_code TEXT NOT NULL,
        act_name TEXT NOT NULL,
        book TEXT,
        title TEXT,
        chapter TEXT,
        section_number TEXT NOT NULL,
        section_title TEXT,
        content TEXT NOT NULL,
        hierarchy_path TEXT NOT NULL,
        offense_type TEXT,
        compoundable INTEGER DEFAULT 0,
        punishment_type TEXT,
        status TEXT DEFAULT 'ACTIVE',
        effective_date TEXT,
        amended_by TEXT
    )
    ''')

    # 2. legal_sections_fts
    cursor.execute('''
    CREATE VIRTUAL TABLE IF NOT EXISTS legal_sections_fts USING fts5(
        section_number, section_title, content, hierarchy_path,
        content='legal_sections', content_rowid='id'
    )
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_sections_ai AFTER INSERT ON legal_sections BEGIN
        INSERT INTO legal_sections_fts(rowid, section_number, section_title, content, hierarchy_path)
        VALUES (new.id, new.section_number, new.section_title, new.content, new.hierarchy_path);
    END;
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_sections_au AFTER UPDATE ON legal_sections BEGIN
        INSERT INTO legal_sections_fts(legal_sections_fts, rowid, section_number, section_title, content, hierarchy_path)
        VALUES ('delete', old.id, old.section_number, old.section_title, old.content, old.hierarchy_path);
        INSERT INTO legal_sections_fts(rowid, section_number, section_title, content, hierarchy_path)
        VALUES (new.id, new.section_number, new.section_title, new.content, new.hierarchy_path);
    END;
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_sections_ad AFTER DELETE ON legal_sections BEGIN
        INSERT INTO legal_sections_fts(legal_sections_fts, rowid, section_number, section_title, content, hierarchy_path)
        VALUES ('delete', old.id, old.section_number, old.section_title, old.content, old.hierarchy_path);
    END;
    ''')

    # 3. cross_references
    cursor.execute('''
    CREATE TABLE IF NOT EXISTS cross_references (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        from_section_id INTEGER NOT NULL,
        to_section_id INTEGER NOT NULL,
        relation_type TEXT NOT NULL,
        is_critical INTEGER DEFAULT 0,
        description TEXT,
        FOREIGN KEY(from_section_id) REFERENCES legal_sections(id),
        FOREIGN KEY(to_section_id) REFERENCES legal_sections(id)
    )
    ''')

    # 4. legal_precedents
    cursor.execute('''
    CREATE TABLE IF NOT EXISTS legal_precedents (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        dika_number TEXT NOT NULL,
        year INTEGER,
        is_grand_chamber INTEGER DEFAULT 0,
        case_facts TEXT NOT NULL,
        court_reasoning TEXT NOT NULL,
        related_sections TEXT NOT NULL,
        keywords TEXT
    )
    ''')

    # 5. legal_precedents_fts
    cursor.execute('''
    CREATE VIRTUAL TABLE IF NOT EXISTS legal_precedents_fts USING fts5(
        dika_number, case_facts, court_reasoning, related_sections, keywords,
        content='legal_precedents', content_rowid='id'
    )
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_precedents_ai AFTER INSERT ON legal_precedents BEGIN
        INSERT INTO legal_precedents_fts(rowid, dika_number, case_facts, court_reasoning, related_sections, keywords)
        VALUES (new.id, new.dika_number, new.case_facts, new.court_reasoning, new.related_sections, new.keywords);
    END;
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_precedents_au AFTER UPDATE ON legal_precedents BEGIN
        INSERT INTO legal_precedents_fts(legal_precedents_fts, rowid, dika_number, case_facts, court_reasoning, related_sections, keywords)
        VALUES ('delete', old.id, old.dika_number, old.case_facts, old.court_reasoning, old.related_sections, old.keywords);
        INSERT INTO legal_precedents_fts(rowid, dika_number, case_facts, court_reasoning, related_sections, keywords)
        VALUES (new.id, new.dika_number, new.case_facts, new.court_reasoning, new.related_sections, new.keywords);
    END;
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_precedents_ad AFTER DELETE ON legal_precedents BEGIN
        INSERT INTO legal_precedents_fts(legal_precedents_fts, rowid, dika_number, case_facts, court_reasoning, related_sections, keywords)
        VALUES ('delete', old.id, old.dika_number, old.case_facts, old.court_reasoning, old.related_sections, old.keywords);
    END;
    ''')

    # 6. legal_glossary
    cursor.execute('''
    CREATE TABLE IF NOT EXISTS legal_glossary (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        term_th TEXT NOT NULL,
        term_en TEXT,
        definition TEXT NOT NULL,
        source_section TEXT
    )
    ''')

    # 7. legal_glossary_fts
    cursor.execute('''
    CREATE VIRTUAL TABLE IF NOT EXISTS legal_glossary_fts USING fts5(
        term_th, term_en, definition, source_section,
        content='legal_glossary', content_rowid='id'
    )
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_glossary_ai AFTER INSERT ON legal_glossary BEGIN
        INSERT INTO legal_glossary_fts(rowid, term_th, term_en, definition, source_section)
        VALUES (new.id, new.term_th, new.term_en, new.definition, new.source_section);
    END;
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_glossary_au AFTER UPDATE ON legal_glossary BEGIN
        INSERT INTO legal_glossary_fts(legal_glossary_fts, rowid, term_th, term_en, definition, source_section)
        VALUES ('delete', old.id, old.term_th, old.term_en, old.definition, old.source_section);
        INSERT INTO legal_glossary_fts(rowid, term_th, term_en, definition, source_section)
        VALUES (new.id, new.term_th, new.term_en, new.definition, new.source_section);
    END;
    ''')
    cursor.execute('''
    CREATE TRIGGER IF NOT EXISTS legal_glossary_ad AFTER DELETE ON legal_glossary BEGIN
        INSERT INTO legal_glossary_fts(legal_glossary_fts, rowid, term_th, term_en, definition, source_section)
        VALUES ('delete', old.id, old.term_th, old.term_en, old.definition, old.source_section);
    END;
    ''')
    conn.commit()


def get_section_id(cursor, ref):
    if isinstance(ref, tuple):
        if len(ref) == 3:
            law_code, sec_num, act_hint = ref
            cursor.execute("SELECT id FROM legal_sections WHERE section_number=? AND law_code=? AND act_name LIKE ?", (str(sec_num), law_code, f"%{act_hint}%"))
            row = cursor.fetchone()
            if row:
                return row[0]
            return None
        else:
            law_code, sec_num = ref
    else:
        law_code, sec_num = 'PENAL', ref
    cursor.execute("SELECT id FROM legal_sections WHERE section_number=? AND law_code=?", (str(sec_num), law_code))
    row = cursor.fetchone()
    if row:
        return row[0]
    return None


def clear_tables(conn):
    cursor = conn.cursor()
    print("Clearing existing tables for re-seeding...")
    cursor.execute("DELETE FROM cross_references")
    cursor.execute("DELETE FROM legal_precedents")
    cursor.execute("DELETE FROM legal_glossary")
    cursor.execute("DELETE FROM legal_sections")
    # Clean FTS
    try:
        cursor.execute("INSERT INTO legal_sections_fts(legal_sections_fts) VALUES('rebuild')")
        cursor.execute("INSERT INTO legal_precedents_fts(legal_precedents_fts) VALUES('rebuild')")
        cursor.execute("INSERT INTO legal_glossary_fts(legal_glossary_fts) VALUES('rebuild')")
    except Exception:
        pass
    conn.commit()


