def seed_data(conn, force=False):
    cursor = conn.cursor()
    
    cursor.execute("SELECT COUNT(*) FROM legal_sections")
    count = cursor.fetchone()[0]
    if count > 0 and not force:
        print(f"Database already seeded ({count} sections). Use --force to re-seed.")
        return

    if force:
        clear_tables(conn)

    print("Seeding legal sections (Penal, Civil & Commercial, and Special Acts)...")
